add("ex1b", ("कारण बताइए: मार्टिन लूथर मुद्रण के पक्ष में था और उसने इसकी खुलेआम प्रशंसा की।", "કારણ આપો: માર્ટિન લ્યૂથર મુદ્રણના પક્ષમાં હતા અને તેમણે તેની ખુલ્લી પ્રશંસા કરી."),
    {0: ("मुद्रण की मदद से लूथर की पिच्चानवे स्थापनाएँ (1517) और न्यू टेस्टामेंट का उनका अनुवाद भारी संख्या में छपकर व्यापक रूप से पढ़े गए, जिससे चर्च की उनकी आलोचना फैली।", "મુદ્રણની મદદથી લ્યૂથરના પંચાણું સિદ્ધાંતો (1517) અને ન્યૂ ટેસ્ટામેન્ટનો તેમનો અનુવાદ મોટી સંખ્યામાં છપાઈને વ્યાપક રીતે વંચાયા, જેથી ચર્ચની તેમની ટીકા ફેલાઈ."), 1: ("इससे प्रोटेस्टेंट धर्मसुधार शुरू हुआ; इसलिए उन्होंने कहा, 'मुद्रण ईश्वर की दी हुई महानतम देन है, सबसे बड़ा तोहफ़ा।'", "તેનાથી પ્રૉટેસ્ટન્ટ ધર્મસુધારણા શરૂ થઈ; તેથી તેમણે કહ્યું, 'મુદ્રણ ઈશ્વરની આપેલી સૌથી મોટી અને અંતિમ ભેટ છે.'")})
add("ex1c", ("कारण बताइए: रोमन कैथोलिक चर्च ने सोलहवीं सदी के मध्य से प्रतिबंधित किताबों की सूची रखनी शुरू कर दी।", "કારણ આપો: રોમન કૅથલિક ચર્ચે સોળમી સદીના મધ્યથી પ્રતિબંધિત પુસ્તકોની યાદી રાખવાનું શરૂ કર્યું."),
    {0: ("लोकप्रिय पठन से मिलर मेनोकियो जैसे लोग बाइबिल की नई व्याख्या करने और चर्च की शिक्षाओं पर प्रश्न उठाने लगे।", "લોકપ્રિય વાંચનથી ઘંટીવાળા મેનોકિયો જેવા લોકો બાઇબલનું નવું અર્થઘટન કરવા અને ચર્ચના ઉપદેશો પર પ્રશ્ન ઉઠાવવા લાગ્યા."), 1: ("ऐसे विधर्मी विचारों से परेशान होकर चर्च ने प्रकाशकों और पुस्तक-विक्रेताओं पर नियंत्रण लगाए और 1558 से प्रतिबंधित किताबों की सूची रखी।", "આવા પાખંડી વિચારોથી પરેશાન થઈને ચર્ચે પ્રકાશકો અને પુસ્તકવિક્રેતાઓ પર નિયંત્રણ મૂક્યાં અને 1558થી પ્રતિબંધિત પુસ્તકોની યાદી રાખી.")})
add("ex1d", ("कारण बताइए: गांधी ने कहा कि स्वराज की लड़ाई दरअसल अभिव्यक्ति, प्रेस और सामूहिकता की आज़ादी की लड़ाई है।", "કારણ આપો: ગાંધીજીએ કહ્યું કે સ્વરાજની લડત ખરેખર વાણી, પ્રેસ અને સંગઠનની સ્વતંત્રતાની લડત છે."),
    {0: ("औपनिवेशिक सरकार वर्नाक्युलर प्रेस एक्ट जैसे क़ानूनों और तिलक जैसे लेखकों को जेल भेजकर इन आज़ादियों को कुचलती थी।", "સંસ્થાનવાદી સરકાર વર્નાક્યુલર પ્રેસ ઍક્ટ જેવા કાયદાઓ અને ટિળક જેવા લેખકોને જેલમાં મોકલીને આ સ્વતંત્રતાઓ દબાવતી."), 1: ("अभिव्यक्ति, प्रेस और संगठन की आज़ादी के बिना भारतीय अपने विचार नहीं रख सकते थे, संगठित नहीं हो सकते थे और औपनिवेशिक शासन का विरोध नहीं कर सकते थे, इसलिए ये आज़ादियाँ स्वराज का आधार थीं।", "વાણી, પ્રેસ અને સંગઠનની સ્વતંત્રતા વિના ભારતીયો પોતાના વિચારો રજૂ કરી શકતા ન હતા, સંગઠિત થઈ શકતા ન હતા અને સંસ્થાનવાદી શાસનનો વિરોધ કરી શકતા ન હતા, તેથી આ સ્વતંત્રતાઓ સ્વરાજનો આધાર હતી.")})
add("ex2a", ("गुटेनबर्ग प्रेस पर छोटी टिप्पणी लिखिए।", "ગુટેનબર્ગ પ્રેસ પર ટૂંકનોંધ લખો."),
    {0: ("व्यापारी के बेटे योहान गुटेनबर्ग ने अपनी जागीर पर शराब और जैतून की प्रेस देखीं, सुनार बने और सीसे के साँचे बनाना सीखा।", "વેપારીના પુત્ર યોહાન ગુટેનબર્ગે પોતાની જાગીર પર દારૂ અને ઑલિવની પ્રેસ જોઈ, સોની બન્યા અને સીસાનાં બીબાં બનાવતાં શીખ્યા."),
     1: ("उन्होंने जैतून की प्रेस को छापेख़ाने का मॉडल और साँचों से अक्षरों के धातु के टाइप बनाए; 1448 तक यह प्रणाली पूरी हुई।", "તેમણે ઑલિવની પ્રેસને છાપખાનાનું મૉડલ અને બીબાંથી અક્ષરોના ધાતુના ટાઇપ બનાવ્યા; 1448 સુધીમાં આ પદ્ધતિ પૂર્ણ થઈ."),
     2: ("उन्होंने पहली किताब बाइबिल छापी: तीन साल में लगभग 180 प्रतियाँ। 1450 से 1550 के बीच छापेख़ाने पूरे यूरोप में फैले, जिससे मुद्रण क्रांति आई।", "તેમણે પહેલું પુસ્તક બાઇબલ છાપ્યું: ત્રણ વર્ષમાં આશરે 180 નકલો. 1450થી 1550 વચ્ચે છાપખાનાં આખા યુરોપમાં ફેલાયાં, જેથી મુદ્રણ ક્રાંતિ આવી.")})
add("ex2b", ("छपी किताब को लेकर इरैस्मस के विचार पर छोटी टिप्पणी लिखिए।", "છપાયેલા પુસ્તક અંગે ઇરૅસ્મસના વિચાર પર ટૂંકનોંધ લખો."),
    {0: ("लैटिन विद्वान और कैथोलिक सुधारक इरैस्मस मुद्रण को लेकर बहुत चिंतित थे।", "લૅટિન વિદ્વાન અને કૅથલિક સુધારક ઇરૅસ્મસ મુદ્રણ અંગે ખૂબ ચિંતિત હતા."),
     1: ("उन्हें लगता था कि कुछ किताबें भले ही कुछ काम की बातें बताएँ, पर अधिकांश निंदनीय, राजद्रोही, अधार्मिक और मूर्खतापूर्ण हैं, और मक्खियों के झुंड की तरह हर जगह फैल रही हैं।", "તેમને લાગતું કે કેટલાંક પુસ્તકો ભલે કામની વાતો આપે, પણ મોટા ભાગનાં નિંદાજનક, રાજદ્રોહી, અધાર્મિક અને મૂર્ખતાભર્યાં છે, અને માખીઓનાં ટોળાંની જેમ બધે ફેલાઈ રહ્યાં છે."),
     2: ("उन्हें डर था कि मुद्रक दुनिया को ज्ञान के लिए हानिकारक किताबों से भर देंगे, जो दिखाता है कि आसान छपाई से ख़तरनाक विचार फैलने का डर था।", "તેમને ડર હતો કે મુદ્રકો વિશ્વને જ્ઞાન માટે હાનિકારક પુસ્તકોથી ભરી દેશે, જે દર્શાવે છે કે સરળ છાપકામથી ખતરનાક વિચારો ફેલાવાનો ડર હતો.")})
add("ex2c", ("वर्नाक्युलर या देसी प्रेस एक्ट पर छोटी टिप्पणी लिखिए।", "વર્નાક્યુલર પ્રેસ ઍક્ટ પર ટૂંકનોંધ લખો."),
    {0: ("1857 के बाद देसी अख़बार मुखर रूप से राष्ट्रवादी हो गए, और अंग्रेज़ों ने 'देसी' प्रेस पर नियंत्रण की माँग की।", "1857 પછી દેશી અખબારો સ્પષ્ટપણે રાષ્ટ્રવાદી બન્યાં, અને અંગ્રેજોએ 'દેશી' પ્રેસ પર નિયંત્રણની માગણી કરી."),
     1: ("आयरिश प्रेस क़ानूनों पर आधारित 1878 के वर्नाक्युलर प्रेस एक्ट ने सरकार को देसी अख़बारों की रिपोर्टों और संपादकीयों को सेंसर करने का व्यापक अधिकार दिया।", "આઇરિશ પ્રેસ કાયદાઓ પર આધારિત 1878ના વર્નાક્યુલર પ્રેસ ઍક્ટે સરકારને દેશી અખબારોના અહેવાલો અને તંત્રીલેખોને સેન્સર કરવાનો વ્યાપક અધિકાર આપ્યો."),
     2: ("राजद्रोही रिपोर्ट छापने वाले अख़बारों को चेतावनी दी जाती, और अनदेखी करने पर उनकी प्रेस ज़ब्त और मशीनें क़ब्ज़े में ली जा सकती थीं; फिर भी राष्ट्रवादी अख़बार बढ़ते गए।", "રાજદ્રોહી અહેવાલો છાપતાં અખબારોને ચેતવણી અપાતી, અને અવગણના થાય તો તેમની પ્રેસ જપ્ત અને યંત્રો કબજે લઈ શકાતાં; છતાં રાષ્ટ્રવાદી અખબારો વધતાં ગયાં.")})
add("ex3a", ("उन्नीसवीं सदी में भारत में मुद्रण संस्कृति के प्रसार का महिलाओं के लिए क्या मतलब था?", "ઓગણીસમી સદીમાં ભારતમાં મુદ્રણ સંસ્કૃતિના પ્રસારનો સ્ત્રીઓ માટે શો અર્થ હતો?"),
    {0: ("मध्यवर्गीय घरों में महिलाओं का पढ़ना बढ़ा; उदार पुरुष महिलाओं को घर पर पढ़ाने और स्कूल भेजने लगे, और पत्रिकाएँ महिलाओं के लेख छापने लगीं।", "મધ્યમવર્ગીય ઘરોમાં સ્ત્રીઓનું વાંચન વધ્યું; ઉદાર પુરુષો સ્ત્રીઓને ઘરે ભણાવવા અને શાળાએ મોકલવા લાગ્યા, અને સામયિકો સ્ત્રીઓનાં લખાણ છાપવા લાગ્યાં."),
     1: ("महिलाओं ने अपने जीवन के बारे में लिखा: राशसुंदरी देवी ने छिपकर पढ़ना सीखा और आमार जीबन (1876) लिखी; कैलाशबाशिनी देवी, ताराबाई शिंदे और पंडिता रमाबाई ने महिलाओं के उत्पीड़न और विधवाओं की दुर्दशा पर लिखा।", "સ્ત્રીઓએ પોતાના જીવન વિશે લખ્યું: રાસસુંદરી દેવીએ છુપાઈને વાંચતાં શીખ્યું અને આમાર જીબન (1876) લખી; કૈલાશબાશિની દેવી, તારાબાઈ શિંદે અને પંડિતા રમાબાઈએ સ્ત્રીઓ પરના અત્યાચાર અને વિધવાઓની દુર્દશા પર લખ્યું."),
     2: ("फेरीवालों के ज़रिए बटतला की सस्ती किताबें महिलाओं तक पहुँचीं, जिससे वे फ़ुरसत में पढ़ सकीं, हालाँकि रूढ़िवादी शिक्षित महिलाओं से डरते थे और कुछ किताबें आज्ञाकारिता सिखाती थीं।", "ફેરિયાઓ દ્વારા બટતલાનાં સસ્તાં પુસ્તકો સ્ત્રીઓ સુધી પહોંચ્યાં, જેથી તે ફુરસદમાં વાંચી શકી, જોકે રૂઢિચુસ્તો શિક્ષિત સ્ત્રીઓથી ડરતા અને કેટલાંક પુસ્તકો આજ્ઞાંકિતતા શીખવતાં.")})
add("ex3b", ("उन्नीसवीं सदी में भारत में मुद्रण संस्कृति के प्रसार का ग़रीब जनता के लिए क्या मतलब था?", "ઓગણીસમી સદીમાં ભારતમાં મુદ્રણ સંસ્કૃતિના પ્રસારનો ગરીબ જનતા માટે શો અર્થ હતો?"),
    {0: ("मद्रासी शहरों के चौराहों पर बिकने वाली बहुत सस्ती छोटी किताबों और 20वीं सदी की शुरुआत से खुले सार्वजनिक पुस्तकालयों ने ग़रीबों को पढ़ने का अवसर दिया।", "મદ્રાસી નગરોના ચોરાહે વેચાતાં ખૂબ સસ્તાં નાનાં પુસ્તકો અને 20મી સદીની શરૂઆતથી ખૂલેલાં જાહેર પુસ્તકાલયોએ ગરીબોને વાંચવાની તક આપી."),
     1: ("ज्योतिबा फुले (गुलामगिरी), आंबेडकर और पेरियार जैसे लेखकों ने जाति-भेद के विरुद्ध लिखा, और उनके लेख पूरे भारत में पढ़े गए।", "જ્યોતિબા ફુલે (ગુલામગીરી), આંબેડકર અને પેરિયાર જેવા લેખકોએ જ્ઞાતિભેદ વિરુદ્ધ લખ્યું, અને તેમનાં લખાણો આખા ભારતમાં વંચાયાં."),
     2: ("मज़दूरों ने भी लिखा: काशीबाबा की छोटे और बड़े का सवाल (1938) ने जाति और वर्ग के शोषण को जोड़ा, और बंबई तथा बंगलौर के मिल-मज़दूरों ने पुस्तकालय बनाए।", "મજૂરોએ પણ લખ્યું: કાશીબાબાની છોટે ઔર બડે કા સવાલ (1938)એ જ્ઞાતિ અને વર્ગના શોષણને જોડ્યું, અને મુંબઈ તથા બેંગલોરના મિલ-મજૂરોએ પુસ્તકાલયો સ્થાપ્યાં.")})
add("ex3c", ("उन्नीसवीं सदी में भारत में मुद्रण संस्कृति के प्रसार का सुधारकों के लिए क्या मतलब था?", "ઓગણીસમી સદીમાં ભારતમાં મુદ્રણ સંસ્કૃતિના પ્રસારનો સુધારકો માટે શો અર્થ હતો?"),
    {0: ("सुधारकों ने पुस्तिकाओं और अख़बारों से अपने विचार आम लोगों की रोज़मर्रा की भाषा में फैलाए और व्यापक जनता तक पहुँचे।", "સુધારકોએ પુસ્તિકાઓ અને અખબારોથી પોતાના વિચારો સામાન્ય લોકોની રોજિંદી ભાષામાં ફેલાવ્યા અને વ્યાપક જનતા સુધી પહોંચ્યા."),
     1: ("राममोहन राय के संवाद कौमुदी (1821) ने विधवा-दहन और मूर्तिपूजा के विरुद्ध तर्क दिए, जबकि रूढ़िवादियों ने समाचार चंद्रिका से जवाब दिया, जिससे सुधार एक सार्वजनिक बहस बन गया।", "રામમોહન રાયના સંવાદ કૌમુદી (1821)એ વિધવા-દહન અને મૂર્તિપૂજા વિરુદ્ધ દલીલો કરી, જ્યારે રૂઢિચુસ્તોએ સમાચાર ચંદ્રિકાથી જવાબ આપ્યો, જેથી સુધારો જાહેર ચર્ચા બન્યો."),
     2: ("फुले, आंबेडकर और पेरियार ने जाति के विरुद्ध मुद्रण का प्रयोग किया, और मुस्लिम उलमा तथा हिंदू समूहों ने धार्मिक ज्ञान फैलाने और समुदायों को जोड़ने के लिए इसका प्रयोग किया।", "ફુલે, આંબેડકર અને પેરિયારે જ્ઞાતિ વિરુદ્ધ મુદ્રણનો ઉપયોગ કર્યો, અને મુસ્લિમ ઉલેમા તથા હિંદુ જૂથોએ ધાર્મિક જ્ઞાન ફેલાવવા અને સમુદાયોને જોડવા તેનો ઉપયોગ કર્યો.")})
add("ex4", ("अठारहवीं सदी के यूरोप में कुछ लोगों को क्यों ऐसा लगता था कि मुद्रण संस्कृति से निरंकुशवाद का अंत, और ज्ञानोदय होगा?", "અઢારમી સદીના યુરોપમાં કેટલાક લોકોને કેમ એવું લાગતું કે મુદ્રણ સંસ્કૃતિથી આપખુદશાહીનો અંત અને જ્ઞાનોદય થશે?"),
    {0: ("मुद्रण से किताबें सस्ती और सुलभ हुईं, और यूरोप के कुछ भागों में साक्षरता 60–80 प्रतिशत तक पहुँचकर पढ़ने का जुनून पैदा हुआ।", "મુદ્રણથી પુસ્તકો સસ્તાં અને સુલભ બન્યાં, અને યુરોપના કેટલાક ભાગોમાં સાક્ષરતા 60–80 ટકા સુધી પહોંચી વાંચનનો જુવાળ આવ્યો."),
     1: ("न्यूटन, टॉमस पेन, वॉल्तेयर और रूसो जैसे वैज्ञानिकों और दार्शनिकों के विचार आम पाठकों तक पहुँचे।", "ન્યૂટન, ટૉમસ પેઇન, વૉલ્ટેર અને રુસો જેવા વૈજ્ઞાનિકો અને તત્ત્વચિંતકોના વિચારો સામાન્ય વાચકો સુધી પહોંચ્યા."),
     2: ("इन लेखों ने परंपरा, अंधविश्वास और निरंकुशता की आलोचना की और तर्क के शासन की वकालत की, चर्च और राजतंत्र की सत्ता पर प्रश्न उठाए।", "આ લખાણોએ પરંપરા, અંધશ્રદ્ધા અને આપખુદશાહીની ટીકા કરી અને તર્કના શાસનની હિમાયત કરી, ચર્ચ અને રાજાશાહીની સત્તા પર પ્રશ્ન ઉઠાવ્યા."),
     3: ("मुद्रण ने बहस की ऐसी संस्कृति बनाई जिसमें तर्क की शक्ति से परिचित जनता ने सभी मूल्यों और संस्थाओं की फिर से जाँच की।", "મુદ્રણે ચર્ચાની એવી સંસ્કૃતિ ઊભી કરી જેમાં તર્કની શક્તિથી પરિચિત જનતાએ બધાં મૂલ્યો અને સંસ્થાઓની ફરી તપાસ કરી."),
     4: ("इसलिए मर्सिए जैसे लेखक मानते थे कि छापाख़ाना प्रगति का सबसे ताक़तवर औज़ार है, और उन्होंने लिखा, 'तो निरंकुशवादियो, अब काँपने का समय आ गया है!'", "તેથી મર્સિયે જેવા લેખકો માનતા કે છાપખાનું પ્રગતિનું સૌથી શક્તિશાળી સાધન છે, અને તેમણે લખ્યું, 'તો જુલમીઓ, હવે ધ્રૂજો!'")})
add("ex5", ("कुछ लोग किताबों की सुलभता को लेकर चिंतित क्यों थे? यूरोप और भारत से एक-एक उदाहरण लेकर समझाइए।", "કેટલાક લોકો પુસ્તકોની સુલભતા અંગે ચિંતિત કેમ હતા? યુરોપ અને ભારતમાંથી એક-એક ઉદાહરણ લઈ સમજાવો."),
    {0: ("कई लोगों को डर था कि छपी और पढ़ी जाने वाली चीज़ों पर नियंत्रण न रहा तो विद्रोही और अधार्मिक विचार फैलेंगे और 'मूल्यवान' साहित्य की सत्ता नष्ट हो जाएगी।", "ઘણાને ડર હતો કે છપાતી અને વંચાતી વસ્તુઓ પર નિયંત્રણ નહિ રહે તો બળવાખોર અને અધાર્મિક વિચારો ફેલાશે અને 'મૂલ્યવાન' સાહિત્યની સત્તા નષ્ટ થશે."),
     1: ("यूरोप: रोमन कैथोलिक चर्च को डर था कि लोकप्रिय पठन से आस्था पर प्रश्न उठेंगे; लूथर की स्थापनाओं और मेनोकियो के मामले के बाद उसने 1558 से प्रतिबंधित किताबों की सूची रखी।", "યુરોપ: રોમન કૅથલિક ચર્ચને ડર હતો કે લોકપ્રિય વાંચનથી શ્રદ્ધા પર પ્રશ્નો ઊઠશે; લ્યૂથરના સિદ્ધાંતો અને મેનોકિયોના કિસ્સા પછી તેણે 1558થી પ્રતિબંધિત પુસ્તકોની યાદી રાખી."),
     2: ("इरैस्मस को भी लगता था कि अधिकांश नई किताबें निंदनीय, राजद्रोही और अधार्मिक हैं।", "ઇરૅસ્મસને પણ લાગતું કે મોટા ભાગનાં નવાં પુસ્તકો નિંદાજનક, રાજદ્રોહી અને અધાર્મિક છે."),
     3: ("भारत: औपनिवेशिक सरकार राष्ट्रवादी आलोचना से डरती थी और उसने देसी प्रेस को सेंसर करने के लिए वर्नाक्युलर प्रेस एक्ट (1878) पास किया, और 1908 में तिलक को क़ैद किया।", "ભારત: સંસ્થાનવાદી સરકાર રાષ્ટ્રવાદી ટીકાથી ડરતી અને તેણે દેશી પ્રેસને સેન્સર કરવા વર્નાક્યુલર પ્રેસ ઍક્ટ (1878) પસાર કર્યો, અને 1908માં ટિળકને કેદ કર્યા."),
     4: ("रूढ़िवादी भारतीयों को भी डर था कि पढ़ना महिलाओं को बिगाड़ देगा: हिंदू मानते थे कि पढ़ी-लिखी लड़की विधवा हो जाएगी, और मुसलमानों को उर्दू के रूमानी अफ़सानों का डर था।", "રૂઢિચુસ્ત ભારતીયોને પણ ડર હતો કે વાંચન સ્ત્રીઓને બગાડશે: હિંદુઓ માનતા કે ભણેલી છોકરી વિધવા બનશે, અને મુસ્લિમોને ઉર્દૂની રોમાંચક વાર્તાઓનો ડર હતો.")})
add("ex6", ("उन्नीसवीं सदी में भारत में ग़रीब जनता पर मुद्रण संस्कृति का क्या असर हुआ?", "ઓગણીસમી સદીમાં ભારતમાં ગરીબ જનતા પર મુદ્રણ સંસ્કૃતિની શી અસર થઈ?"),
    {0: ("मद्रासी शहरों के चौराहों पर सस्ती छोटी किताबें बिकती थीं, इसलिए ग़रीब भी किताबें ख़रीद सकते थे।", "મદ્રાસી નગરોના ચોરાહે સસ્તાં નાનાં પુસ્તકો વેચાતાં, તેથી ગરીબો પણ પુસ્તકો ખરીદી શકતા."),
     1: ("20वीं सदी की शुरुआत से खुले सार्वजनिक पुस्तकालयों ने किताबों तक पहुँच बढ़ाई, जिन्हें प्रायः प्रतिष्ठा चाहने वाले अमीर संरक्षकों ने खोला।", "20મી સદીની શરૂઆતથી ખૂલેલાં જાહેર પુસ્તકાલયોએ પુસ્તકો સુધીની પહોંચ વધારી, જે મોટે ભાગે પ્રતિષ્ઠા ઇચ્છતા ધનિક આશ્રયદાતાઓએ ખોલ્યાં."),
     2: ("जाति-भेद के मुद्दों पर लिखा गया: फुले की गुलामगिरी (1871), और बाद में आंबेडकर और पेरियार, जिनके लेख पूरे भारत में पढ़े गए।", "જ્ઞાતિભેદના મુદ્દાઓ પર લખાયું: ફુલેની ગુલામગીરી (1871), અને પછીથી આંબેડકર અને પેરિયાર, જેમનાં લખાણો આખા ભારતમાં વંચાયાં."),
     3: ("मज़दूरों ने अपने अनुभवों के बारे में लिखा: काशीबाबा की छोटे और बड़े का सवाल (1938) और सुदर्शन चक्र की कविताएँ (सच्ची कविताएँ)।", "મજૂરોએ પોતાના અનુભવો વિશે લખ્યું: કાશીબાબાની છોટે ઔર બડે કા સવાલ (1938) અને સુદર્શન ચક્રની કવિતાઓ (સચ્ચી કવિતાએં)."),
     4: ("बंबई और बंगलौर के मिल-मज़दूरों ने समाज सुधारकों की मदद से ख़ुद को शिक्षित करने के लिए पुस्तकालय बनाए।", "મુંબઈ અને બેંગલોરના મિલ-મજૂરોએ સમાજસુધારકોની મદદથી પોતાને શિક્ષિત કરવા પુસ્તકાલયો સ્થાપ્યાં.")})
add("ex7", ("मुद्रण संस्कृति ने भारत में राष्ट्रवाद के विकास में क्या मदद की?", "મુદ્રણ સંસ્કૃતિએ ભારતમાં રાષ્ટ્રવાદના વિકાસમાં શી મદદ કરી?"),
    {0: ("अख़बार एक जगह की ख़बर दूसरी जगह पहुँचाते थे, जिससे समुदाय जुड़े और अखिल भारतीय पहचान बनी।", "અખબારો એક સ્થળના સમાચાર બીજે પહોંચાડતાં, જેથી સમુદાયો જોડાયા અને અખિલ ભારતીય ઓળખ ઊભી થઈ."),
     1: ("देसी और राष्ट्रवादी अख़बारों ने औपनिवेशिक कुशासन की ख़बरें दीं और राष्ट्रवादी गतिविधियों को प्रोत्साहित किया।", "દેશી અને રાષ્ટ્રવાદી અખબારોએ સંસ્થાનવાદી કુશાસનના સમાચાર આપ્યા અને રાષ્ટ્રવાદી પ્રવૃત્તિઓને પ્રોત્સાહન આપ્યું."),
     2: ("मुद्रण ने सामाजिक और धार्मिक सुधार की बहसें फैलाईं, जिससे लोग परंपरा और औपनिवेशिक सत्ता, दोनों पर प्रश्न उठाने लगे।", "મુદ્રણે સામાજિક અને ધાર્મિક સુધારાની ચર્ચાઓ ફેલાવી, જેથી લોકો પરંપરા અને સંસ્થાનવાદી સત્તા, બંને પર પ્રશ્ન ઉઠાવવા લાગ્યા."),
     3: ("चित्रों, कार्टूनों और कैलेंडरों, और राष्ट्रवादी साहित्य ने राष्ट्रीय विचारों को कम पढ़े-लिखे लोगों तक भी पहुँचाया।", "ચિત્રો, કાર્ટૂન અને કૅલેન્ડર, અને રાષ્ટ્રવાદી સાહિત્યે રાષ્ટ્રીય વિચારોને ઓછું ભણેલા લોકો સુધી પણ પહોંચાડ્યા."),
     4: ("वर्नाक्युलर प्रेस एक्ट जैसे दमन और केसरी में लिखने के लिए तिलक की क़ैद (1908) से व्यापक विरोध हुए, जिससे राष्ट्रवाद और मज़बूत हुआ।", "વર્નાક્યુલર પ્રેસ ઍક્ટ જેવા દમન અને કેસરીમાં લખવા બદલ ટિળકની કેદ (1908)થી વ્યાપક વિરોધ થયો, જેથી રાષ્ટ્રવાદ વધુ મજબૂત બન્યો.")})

